 function rosterRows(id){const ev=data.events?.[id];if(!ev)return [];return [...Object.entries(ev.participants||{}).map(([pid,p])=>({id:pid,name:userById(pid)?.fullName||pid,group:'Música',attended:!!p.attended,external:false})),...Object.entries(ev.externalParticipants||{}).map(([pid,p])=>({id:pid,name:p.fullName||'Sin nombre',group:'Externo',attended:!!p.attended,external:true}))].sort((a,b)=>Number(a.external)-Number(b.external)||a.name.localeCompare(b.name,'es'));}
 function rosterForm(id){if(!eventStaff())return;const ev=data.events?.[id];if(!ev)return;const rows=rosterRows(id);modal('Lista de inscritos',`<header class="sgl565-roster-head"><img class="sgl566-roster-logo" src="assets/ministerio_musica.png" alt="Logo del Sistema de Gestión de Música" width="72" height="72"><span class="eyebrow">Sistema de Gestión de Música</span><h3>${e(ev.name)}</h3><p>${e(ev.date)} · ${e(ev.place||'Lugar por confirmar')} · ${rows.length} inscritos</p><div class="actions">${button('Excel',`SGL550.exportRoster(${JSON.stringify(id)},'xlsx')`)}${button('PDF',`SGL550.exportRoster(${JSON.stringify(id)},'pdf')`)}${button('Inscribir',`SGL550.enrollForm(${JSON.stringify(id)})`,true)}</div></header><div class="table-wrap"><table class="table"><thead><tr><th>Nombre completo</th><th>Lista</th><th>Participó</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${e(p.name)}</td><td>${p.group}</td><td><input type="checkbox" aria-label="Asistencia de ${e(p.name)}" ${p.attended?'checked':''} onchange="SGL550.rosterAttendance(${j(id)},${j(p.id)},${p.external},this.checked)"></td><td>${button('Quitar',`SGL550.removeParticipant(${JSON.stringify(id)},${JSON.stringify(p.id)},${p.external})`)}</td></tr>`).join('')||'<tr><td colspan="4">No hay inscritos.</td></tr>'}</tbody></table></div>`);}
