 async function exportRoster(id,format){if(!eventStaff())return;const ev=data.events?.[id];if(!ev)return;const rows=rosterRows(id),name='Inscritos_'+String(ev.name).replace(/[^\p{L}\p{N}]+/gu,'_');try{
  if(format==='xlsx'){const cells=[['Sistema de Gestión de Música'],['Evento',ev.name],['Fecha',ev.date],['Lugar',ev.place||''],['Total inscritos',String(rows.length)],[],['N.º','Nombre completo','Lista','Participó'],...rows.map((p,i)=>[String(i+1),p.name,p.group,p.attended?'Sí':'No'])];const response=await fetch('assets/ministerio_musica.png');if(!response.ok)throw new Error('No se pudo cargar el logo de Música.');const blob=rosterWorkbook(cells,new Uint8Array(await response.arrayBuffer()));await saveBlobWithDialog(name+'.xlsx',blob,'Libro de Excel|*.xlsx');return;}
  const logo=await jpegResource('assets/ministerio_musica.png',160,true),pages=[];let page,y;const addPage=()=>{page={w:595,h:842,commands:[],images:[]};pages.push(page);const scale=Math.min(52/logo.w,52/logo.h);pdfImage(page,logo,503,28,logo.w*scale,logo.h*scale);pdfText(page,'SISTEMA DE GESTIÓN DE MÚSICA',40,35,15,'AB');pdfText(page,short(ev.name,65),40,62,12,'AB');pdfText(page,short([ev.date,ev.place].filter(Boolean).join(' · '),90),40,84,10,'AR');pdfText(page,'LISTA DE INSCRITOS · Total: '+rows.length,40,106,10,'AB');[['N.º',40],['Nombre completo',72],['Lista',407],['Participó',493]].forEach(([t,x])=>pdfText(page,t,x,135,10,'AB'));pdfText(page,'Página '+pages.length,490,810,9,'AR');y=160;};addPage();for(const [i,p] of rows.entries()){const lines=[];let line='';for(const word of p.name.split(/\s+/)){const candidate=line?line+' '+word:word;if(line&&measureReportText(candidate,10,'AR')>320){lines.push(line);line=word;}else line=candidate;}lines.push(line);const height=Math.max(26,lines.length*14+8);if(y+height>790)addPage();pdfText(page,String(i+1),40,y,10,'AR');lines.forEach((line,n)=>pdfText(page,line,72,y+n*14,10,'AR'));pdfText(page,p.group,407,y,10,'AR');pdfText(page,p.attended?'Sí':'No',493,y,10,'AR');y+=height;}await saveBlobWithDialog(name+'.pdf',buildVectorPdf(pages),'Documento PDF|*.pdf');
 }catch(error){toast('No se pudo exportar la lista: '+error.message);}}
 function filterMembers(value){const options=[...document.querySelectorAll('#sgl550_participant option')],term=String(value||'').trim().toLowerCase();for(const option of options)option.hidden=!option.dataset.search.includes(term);const first=options.find(option=>!option.hidden);document.getElementById('sgl550_participant').value=first?.value||'';}
