 function eligible(u,kind,eventId=''){
  if(!u)return false;const checks=data.completions?.[u.id]||{},year=SGL531.dataFor(SGL531.context('LM-NUT-1',u.id)),forty=SGL531.dataFor(SGL531.context('LM-TEM-1',u.id));
  if(kind==='ministry')return !!u.musicMinistryRegistration?.name;
  if(kind==='forty_days'||kind==='forty_dawns'){const p=v3EnsureProgramProgress(u.id,PROGRAM),s=p.submissions['LM-TEM-1'];if(p.status['LM-TEM-1']==='approved'&&s?.primaryDocumentId&&String(s.submissionMode||s.deliveryMode||'').trim().toLowerCase()==='document')return true;}
  if(kind==='forty_days'||kind==='forty_dawns')return SGL531Model.completeEntries('LM-TEM-1',forty,localDate()).length===40;
  if(kind==='year'||kind==='reavivados')return year.choice!=='bible_plan'&&(!!checks.reavivados?.concluded||year.choice==='reavivados'&&SGL531Model.keysFor('LM-NUT-1',year).length>0&&SGL531Model.keysFor('LM-NUT-1',year).every(k=>SGL531Model.completeEntries('LM-NUT-1',year,localDate()).includes(k)));
  if(kind==='bible_plan')return year.choice!=='reavivados'&&!!checks.bible_plan?.concluded;
  if(kind==='final')return complete(u)&&data.workflow?.[u.id]?.state==='approved'&&String(data.workflow?.[u.id]?.approvedAt||'').slice(0,4)>='2026';
  const ev=data.events?.[eventId];if(!ev||String(ev.date||'')<'2026-01-01')return false;if(ev.templateId610&&eventKind(ev)===kind&&ev.participants?.[u.id]?.attended)return true;return !!ev&&eventKind(ev)===kind&&ev.participants?.[u.id]?.attended&&ev.date<=localDate()&&(kind!=='leadership'||Number(ev.hours)>=10)&&(kind!=='egw_reading'||!!String(ev.bookTitle||'').trim());
 }
 function certificates(u){if(!u)return '<p>No hay miembros aspirantes.</p>';const canConclude=SGLMusicPolicy560.cap(currentUser(),'annual')&&currentUser()?.id!==u.id&&members().some(member=>member.id===u.id),choice=annualChoice(u),status=v3EnsureProgramProgress(u.id,PROGRAM).status['LM-NUT-1'],earned=[];for(const [kind,title] of Object.entries(TYPES)){if(kind==='ministry'&&data.ministryLinks610?.[u.id])continue;if(['leadership','beliefs','egw_reading'].includes(kind)){for(const ev of Object.values(data.events||{}).filter(event=>eligible(u,kind,event.id)))earned.push({kind,title,event:ev});continue;}if(kind==='year'&&eligible(u,'reavivados')||kind==='reavivados'&&choice==='bible_plan')continue;if(eligible(u,kind))earned.push({kind,title,event:null});}return `${canConclude?`<details class="card sgl563-cert-admin"><summary>Validar conclusión de lectura anual</summary><p>Valida la modalidad elegida para habilitar su revisión.</p><div class="actions">${button('Reavivados · Concluido',`SGL550.conclude('reavivados',${JSON.stringify(u.id)})`,false,choice!=='reavivados'||['in_review','approved'].includes(status)||!!data.completions?.[u.id]?.reavivados?.concluded)}${button('Bible Plan · Concluido',`SGL550.conclude('bible_plan',${JSON.stringify(u.id)})`,false,choice!=='bible_plan'||['in_review','approved'].includes(status)||!!data.completions?.[u.id]?.bible_plan?.concluded)}</div></details>`:''}<section class="sgl563-certificate-list" aria-label="Cursos y certificados obtenidos">${earned.map(item=>{const ev=item.event,detail=ev?[ev.date,ev.place].filter(Boolean).join(' · '):item.kind==='ministry'?'Registro del Ministerio':item.kind==='final'?'Trayectoria musical aprobada':'Curso completado';const eventArg=ev?`,${JSON.stringify(ev.id)}`:'';return `<article class="card sgl563-certificate-row" data-certificate-key="${e(u.id+':'+item.kind+':'+(ev?.id||''))}"><span class="sgl563-certificate-mark">${icon('certificates')}</span><span class="sgl563-certificate-name"><strong>${e(ev?.name||item.title)}</strong><small>${e(detail)}</small></span><span class="chip green">Completado</span><div class="sgl551-certificate-actions">${button('Ver',`SGL550.issue(${JSON.stringify(item.kind)},${JSON.stringify(u.id)},'view'${eventArg})`,true)}${button('Imprimir',`SGL550.issue(${JSON.stringify(item.kind)},${JSON.stringify(u.id)},'print'${eventArg})`)}${button('Descargar',`SGL550.issue(${JSON.stringify(item.kind)},${JSON.stringify(u.id)},'download'${eventArg})`)}${staff()?button('Plantilla',`SGL550.templateForm(${JSON.stringify(item.kind)})`):''}</div></article>`;}).join('')||'<div class="card sgl563-certificate-empty">Todavía no hay cursos concluidos ni eventos con asistencia confirmada.</div>'}</section>${staff()?`<details class="card sgl563-cert-admin"><summary>Administrar plantillas de certificados</summary><p>Las plantillas cargadas tienen prioridad y permiten ajustar nombre, título, datos y QR.</p><div class="actions">${Object.entries(TYPES).map(([kind,title])=>button('Subir · '+title,`SGL550.templateForm(${JSON.stringify(kind)})`)).join('')}</div></details>`:''}`;}
 async function conclude(kind,id){if(!confirm('¿Validar la modalidad elegida como concluida? El aspirante podrá enviarla a revisión después.'))return;if(await operation('conclude',{kind},id)){render();toast('Conclusión validada. El aspirante ya puede enviar a revisión.');}}
